#!/usr/bin/env bash
# THE C++ ORDERING RULE, HELD AGAINST WHAT THE TYPESCRIPT ACTUALLY DID.
#
# This is the one rule that had to be written twice, because only the receiver
# can decide which of several envelopes arriving over a real network to apply.
# Two implementations of one rule drift silently, and this one drifts in the
# worst direction: a port that got revision-before-sequence slightly wrong looks
# correct for every ordinary stream and goes backwards only during a reconnect
# onto a stale replica — the exact moment anybody is watching.
#
# So the cases are GENERATED by running the real TypeScript, and this replays
# each through the C++ and compares the verdict AND the whole folded cursor.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SRC="$HERE/../Source/Wonderland"
STUBS="$HERE/SyntaxStubs"
OUT="$(mktemp -d)"
trap 'rm -rf "$OUT"' EXIT

# BUILT AND RUN TWICE, UNOPTIMISED AND OPTIMISED. See geometry-parity-check.sh
# for the defect that made this necessary: a hand-written stub returned a
# dangling reference, every check passed at -O0, and the same build aborted
# under optimisation. The disagreement between the levels is the signal.
SANITIZE="-g -fsanitize=address,undefined -fno-sanitize-recover=all"

build_harness() {
	# shellcheck disable=SC2086
	g++ -std=c++17 "$1" $SANITIZE -I"$STUBS" -I"$SRC" \
	  "$HERE/OrderingHarness/main.cpp" \
	  "$SRC/WonderlandOrdering.cpp" \
	  "$SRC/WonderlandOrdering.cases.cpp" \
	  "$SRC/WonderlandEnvelope.cpp" \
	  -o "$2"
}

# The output is shown when it fails, which sounds obvious and was not: under
# `set -e` a failing harness exited before anything was printed, so deliberate
# mutations came back as a bare exit code with the diagnosis stuck in a temp
# file the EXIT trap then deleted.
run_harness() {
	local bin="$1" out="$2"
	if ! "$bin" > "$out" 2>&1; then
		echo "FAIL $(basename "$bin") reported failures:"
		cat "$out"
		exit 1
	fi
}

build_harness -O0 "$OUT/harness-O0"
build_harness -O2 "$OUT/harness-O2"
run_harness "$OUT/harness-O0" "$OUT/out-O0.txt"
run_harness "$OUT/harness-O2" "$OUT/out-O2.txt"

if ! diff -q "$OUT/out-O0.txt" "$OUT/out-O2.txt" > /dev/null; then
	echo "FAIL the ordering rule behaves differently at -O0 and -O2:"
	diff "$OUT/out-O0.txt" "$OUT/out-O2.txt" | head -10
	exit 1
fi
cat "$OUT/out-O2.txt"
